{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Tacrolimus, a complex lipophilic macrocyclic lactone, has a mean oral bioavailability of 25% in liver transplant recipients, demonstrating that complex polycyclic lactone natural products can exceed the 20% threshold despite poor solubility.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Vorapaxar, a large lipophilic non-ionizable molecule, shows approximately 100% oral bioavailability, supporting high absorption for lipophilic compounds without ionizable groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Posaconazole, a large lipophilic azole, has 96% oral bioavailability, indicating that poorly soluble lipophilic drugs can still achieve high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Amphotericin B has negligible oral bioavailability due to poor permeability and solubility, but its much larger size and high polarity make it a weak counterexample for the smaller, more lipophilic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic, neutral polycyclic diterpenoid lactone. High-transfer evidence from tacrolimus (25%), vorapaxar (~100%), and posaconazole (96%) supports that complex lipophilic molecules can achieve oral bioavailability above the 20% threshold. The only low-F evidence, amphotericin B, comes from a much larger and highly polar polyene with poor permeability, which is not representative of the query. Therefore, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query or a close structural analog.",
    "Fasted-state solubility and first-pass metabolism of this specific diterpenoid lactone are unknown.",
    "The most relevant complex lactone comparator, tacrolimus, has bioavailability near the 20% threshold, leaving some margin uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

